 108: def scored(
 109:     owner: Candidate,
 110:     *,
 111:     n: int = 9,
 112:     per_episode: dict[int, dict[str, object]] | None = None,
 113:     common: dict[str, object] | None = None,
 114:     seeds: range | None = None,
 115: ) -> tuple[CandidateEvidence, dict[str, EpisodeMetricSet]]:
 116:     per_episode = per_episode or {}
 117:     contexts = [context(seed) for seed in (seeds or range(n))]
 118:     metrics = [
 119:         episode(owner, ctx, **{**(common or {}), **per_episode.get(index, {})})
 120:         for index, ctx in enumerate(contexts)
 121:     ]
 122:     return build_evidence(owner, metrics, contexts, anchors(), SETTINGS), index_metrics(metrics)
