629: export function runOutcome(run: DecisionRun): RunOutcome {
630:   const candidates = run.report?.candidates ?? [];
631:   const recommended = candidates.find(
632:     (candidate) => candidate.candidate_id === run.recommended_candidate_id,
633:   );
634:   return {
635:     winner: recommended
636:       ? `${recommended.stack_label} Â· ${recommended.local_controller_config}`
637:       : // The hash, only when the report cannot name the winner â€” better
638:         // than an em dash on a run that did recommend somebody.
639:         run.recommended_candidate_id,
640:     cleared: candidates.filter((candidate) => candidate.cleared_gates).length,
641:     total: candidates.length,
642:   };
