 1: /** Which two candidates a comparison page is about, and where each run
 2:  *  is at a given arc length.
 3:  *
 4:  * Extracted from the page so it can be *tested as behaviour*. The page
 5:  * itself is only assertable as source text in this suite (no jsdom, no
 6:  * testing-library â€” see `vitest.config.ts`), and the defect that
 7:  * motivated this file went straight through those assertions: the page
 8:  * showed `candidates.slice(0, 2)` while the exemplar recipe ran on a
 9:  * different pair, and every string a source-text test looked for was
10:  * present in both versions.
11:  */
12: 
13: import type { DecisionRun, ReplaySyncView, RunCandidate } from "./decisions";
14: 
15: /** The recommendation and its runner-up, in that order.
16:  *
17:  * **From the card, never from list order.** `report.candidates` is in
18:  * registration order; its first entry can be a candidate a gate
19:  * eliminated before any Î”U existed. The card is where the run says who
20:  * won, and the exemplar recipe on the server reads the same field â€” so
21:  * the panel and the four roles are about the same two candidates by
22:  * construction rather than by coincidence.
23:  *
24:  * `null` when the run produced no card: with no ranking there is no
25:  * winner, and picking two anyway is how "best for A" ends up over a
26:  * candidate that lost.
27:  */
28: export function comparedPair(run: DecisionRun): [string, string] | null {
29:   const card = run.card ?? (run.report?.decision_card as Record<string, unknown> | null);
30:   if (!card || typeof card !== "object") return null;
31:   const recommended = (card as { recommended?: { candidate_id?: string } }).recommended;
32:   const alternative = (card as { alternative?: { candidate_id?: string } }).alternative;
33:   const winner = recommended?.candidate_id ?? "";
34:   const runnerUp = alternative?.candidate_id ?? "";
35:   if (!winner || !runnerUp || winner === runnerUp) return null;
36:   return [winner, runnerUp];
37: }
38: 
39: /** The two candidates to draw, winner first.
40:  *
41:  * Falls back to the first two entries only when the run has no card â€”
42:  * a comparison that ranked nobody still has two canvases worth showing,
43:  * and there is no winner to get the order wrong.
44:  */
45: export function panelCandidates(run: DecisionRun, candidates: RunCandidate[]): RunCandidate[] {
46:   const pair = comparedPair(run);
47:   if (!pair) return candidates.slice(0, 2);
48:   const byId = new Map(candidates.map((candidate) => [candidate.candidate_id, candidate]));
49:   const ordered = pair.map((id) => byId.get(id)).filter((c): c is RunCandidate => Boolean(c));
50:   return ordered.length === 2 ? ordered : candidates.slice(0, 2);
51: }
52: 
53: /** How far both runs got. Past this the panels are not comparable, so
54:  *  the slider stops there rather than showing one robot alone. */
55: export function commonProgress(view: ReplaySyncView): number {
56:   const both = view.plan.rows.filter((row) => row.time_a !== null && row.time_b !== null);
57:   return both.length > 0 ? both[both.length - 1].progress_m : 0;
58: }
59: 
60: /** The timestamp one side had reached at this arc length.
61:  *
62:  * The two sides deliberately return *different* timestamps for the same
63:  * progress â€” that is the whole difference between the alignments, and
64:  * the reason the warning travels with the rows.
65:  */
66: export function sideTime(
67:   view: ReplaySyncView | null,
68:   progress: number,
69:   side: "a" | "b",
70: ): number {
71:   if (!view || view.plan.rows.length === 0) return 0;
72:   let chosen = view.plan.rows[0];
73:   for (const row of view.plan.rows) {
74:     if (row.progress_m > progress) break;
75:     chosen = row;
76:   }
77:   const stamp = side === "a" ? chosen.time_a : chosen.time_b;
78:   return stamp ?? 0;
79: }

  1: /** The progress-sync panel, rendered.
  2:  *
  3:  * `renderToStaticMarkup` is what this suite has â€” no jsdom, no
  4:  * testing-library (see `vitest.config.ts`), so a click cannot be
  5:  * simulated. First render still answers the question that matters here:
  6:  * can a reader be shown arc-length-aligned panels *without* the
  7:  * sentence saying the two runs were there at different times.
  8:  */
  9: 
 10: import { renderToStaticMarkup } from "react-dom/server";
 11: import { describe, expect, it } from "vitest";
 12: 
 13: import { ProgressSync } from "@/components/ProgressSync";
 14: import type { ReplaySyncView, RunCandidate } from "@/lib/decisions";
 15: import { initialPlayback } from "@/lib/playback";
 16: 
 17: const WARNING =
 18:   "same place is not the same situation: the two runs reached this point at different times.";
 19: 
 20: function view(overrides: Partial<ReplaySyncView> = {}): ReplaySyncView {
 21:   return {
 22:     episode_context_id: "ctx",
 23:     candidate_a: "winner",
 24:     candidate_b: "runner_up",
 25:     plan: {
 26:       reference: { points: [], quality: "degraded_candidate_path" },
 27:       rows: [
 28:         { progress_m: 0, time_a: 0, time_b: 0, cross_track_a: 0, cross_track_b: 0 },
 29:         { progress_m: 4, time_a: 4, time_b: 9, cross_track_a: 0, cross_track_b: 1.2 },
 30:       ],
 31:       backward_samples_a: 0,
 32:       backward_samples_b: 0,
 33:       warning: WARNING,
 34:     },
 35:     divergence: {
 36:       sustained: {
 37:         kind: "sustained_cross_track",
 38:         progress_m: 3.25,
 39:         time_a: 3.2,
 40:         time_b: 7.1,
 41:         separation_m: 0.6,
 42:         event: null,
 43:         side: null,
 44:       },
 45:       anchors: [
 46:         {
 47:           kind: "event",
 48:           progress_m: 2,
 49:           time_a: 2,
 50:           time_b: 4,
 51:           separation_m: null,
 52:           event: "replan",
 53:           side: "b",
 54:         },
 55:       ],
 56:     },
 57:     reference_source_candidate_id: "winner",
 58:     ...overrides,
 59:   };
