  1: "use client";
  2: 
  3: /** The arc-length alignment panel: slider, caveat, and where they parted.
  4:  *
  5:  * Its own file rather than a helper inside the page, for two reasons.
  6:  * Next forbids a page module from exporting anything but the route's own
  7:  * hooks, so a component defined there cannot be rendered by a test â€”
  8:  * and this is precisely the component worth rendering in one, because
  9:  * the thing it must never do is show arc-length-aligned panels without
 10:  * the sentence explaining that the two runs were there at different
 11:  * times.
 12:  */
 13: 
 14: import { useTranslation } from "@/lib/i18n";
 15: import type { DivergencePoint, ReplaySyncView, RunCandidate } from "@/lib/decisions";
 16: import type { PlaybackState } from "@/lib/playback";
 17: 
 18: export type SyncSlot =
 19:   | { state: "idle" }
 20:   | { state: "loading" }
 21:   | { state: "ready"; view: ReplaySyncView }
 22:   | { state: "error"; message: string };
 23: 
 24: 
 25: export function ProgressSync({
 26:   sync,
 27:   scan,
 28:   span,
 29:   onScan,
 30:   candidates,
 31: }: {
 32:   sync: SyncSlot;
 33:   scan: PlaybackState;
 34:   span: number;
 35:   onScan: (next: PlaybackState) => void;
 36:   candidates: RunCandidate[];
 37: }) {
 38:   const { t } = useTranslation();
 39:   if (sync.state === "loading" || sync.state === "idle") {
 40:     return <div className="episode-skeleton" role="status">{t("trace.sync.loading")}</div>;
 41:   }
 42:   if (sync.state === "error") {
 43:     return <div className="episode-error" role="alert"><p>{t("trace.sync.error")}</p><p className="muted">{sync.message}</p></div>;
 44:   }
 45: 
 46:   const view: ReplaySyncView = sync.view;
 47:   const ruler = candidates.find((c) => c.candidate_id === view.reference_source_candidate_id);
 48:   const jumps = [
 49:     ...(view.divergence.sustained ? [view.divergence.sustained] : []),
 50:     ...view.divergence.anchors,
 51:   ];
 52: 
 53:   return (
 54:     <div className="episode-progress-sync">
 55:       {/* Served by the platform, rendered verbatim. A caveat the client
 56:           can reword is a caveat the client can water down. */}
 57:       <p className="episode-sync-warning" role="note">{view.plan.warning}</p>
 58:       <p className="muted">
 59:         <span className={`badge ${view.plan.reference.quality === "reference_plan" ? "ok" : "warn"}`}>
 60:           {t(`trace.sync.quality.${view.plan.reference.quality}`)}
 61:         </span>
 62:         {ruler ? ` ${t("trace.sync.ruler")}: ${ruler.stack_label}` : ""}
 63:       </p>
 64:       <div className="episode-playback">
 65:         <button type="button" onClick={() => onScan({ ...scan, playing: !scan.playing && span > 0 })}>
 66:           {scan.playing ? t("trace.pause") : t("trace.play")}
 67:         </button>
 68:         <input
 69:           type="range"
 70:           min={0}
 71:           max={span || 0}
 72:           step="0.01"
 73:           value={Math.min(scan.time, span)}
 74:           aria-label={t("trace.sync.progressLabel")}
 75:           aria-valuetext={`${scan.time.toFixed(1)} / ${span.toFixed(1)} m`}
 76:           onChange={(event) => onScan({ ...scan, playing: false, time: Number(event.target.value) })}
 77:         />
 78:         <output>{scan.time.toFixed(1)} / {span.toFixed(1)} m</output>
 79:       </div>
 80:       {jumps.length > 0 ? (
 81:         <div className="episode-divergence" aria-label={t("trace.sync.divergence")}>
 82:           <span className="muted">{t("trace.sync.divergence")}:</span>
 83:           {jumps.map((point, index) => (
 84:             <button
 85:               key={`${point.kind}-${point.event ?? index}-${point.progress_m}`}
 86:               type="button"
 87:               className="chip"
 88:               onClick={() => onScan({ ...scan, playing: false, time: point.progress_m })}
 89:             >
 90:               {chipLabel(point, t)}
 91:             </button>
 92:           ))}
 93:         </div>
 94:       ) : null}
 95:     </div>
 96:   );
 97: }
 98: 
 99: function chipLabel(point: DivergencePoint, t: (key: string) => string): string {
100:   const where = `${point.progress_m.toFixed(1)} m`;
101:   if (point.kind === "event") return `${point.event} (${point.side?.toUpperCase()}) Â· ${where}`;
102:   return `${t("trace.sync.sustained")} Â· ${where}`;
103: }
