  3: /** Selection runs: the evidence, and the recommendation when there is one.
  4:  *
  5:  * **A run is the record; a card is something a run sometimes produces.**
  6:  * Four of the first five comparisons this platform ran produced no
  7:  * Decision Card, because a card needs two candidates through all six
  8:  * gates and only one got there. Each of those runs still answered "who
  9:  * was eliminated where, after how many runs" â€” the question HÄ-12 puts
 10:  * on a card in the first place.
 11:  *
 12:  * That shapes every type here. `card` is nullable, `report` is not, and
 13:  * nothing in this module treats a missing card as an error state. A UI
 14:  * that could only render a Decision Card would recreate the pressure to
 15:  * make every run rankable, and that pressure is what produced a card
 16:  * bounding a collision probability off a single episode.
 17:  */
 18: 
 19: import { API_BASE } from "./api";
 20: import { FieldError, authFetch } from "./auth";
 21: 
 22: /** Which artifact a run produced. `comparison` covers both a comparison
 23:  *  that could be ranked and one that could not â€” the card's presence is
 24:  *  the distinction. */
 25: export type ArtifactKind = "decision_card" | "comparison" | "measurement";
 26: 
 27: /** Has a human read this run's evidence? Applies to every run. */
 28: export type ReviewState = "unreviewed" | "reviewed";
 29: 
 30: /** Is this run's recommendation the configuration we deploy?
 31:  *
 32:  * `not_applicable` where there is no card â€” not a missing value but a
 33:  * statement: this run recommends nobody, so there is nothing to approve.
 34:  */
 35: export type ConfigState = "not_applicable" | "pending" | "approved" | "rejected";
 36: 
 37: /** One gate's verdict.
 38:  *
 39:  * The wire shape is deliberately mixed: a gate with nothing to explain
 40:  * serialises as the bare string `"pass"`, while one carrying evidence
 41:  * serialises as an object. Both are rendered as the same badge, because
 42:  * a table where G1 is plain text and G2 is a coloured chip reads as if
 43:  * they were different kinds of judgement â€” they are not.
 44:  */
 45: export type GateVerdict = { result: "pass" | "fail"; [field: string]: unknown } | "pass" | "fail";
 46: 
 47: /** The verdict, whichever shape it arrived in. */
 48: export function gateResult(verdict: GateVerdict | undefined): "pass" | "fail" | undefined {
 49:   if (verdict === undefined) return undefined;
 50:   return typeof verdict === "string" ? verdict : verdict.result;
 51: }
 52: 
 53: /** Everything the gate said beyond pass/fail, as label â†’ value.
 54:  *
 55:  * Empty for a bare-string verdict, which is the honest answer: that gate
 56:  * had nothing to add. Never invented, because "G3: fail" with fabricated
 57:  * numbers beside it is worse than "G3: fail" alone.
 58:  */
 59: export function gateEvidence(verdict: GateVerdict | undefined): [string, string][] {
 60:   if (verdict === undefined || typeof verdict === "string") return [];
 61:   return Object.entries(verdict)
 62:     .filter(([key, value]) => key !== "result" && value !== null && value !== undefined)
 63:     .map(([key, value]) => [key, String(value)]);
 64: }
 65: 
 66: /** Why a candidate stopped before the others (early stop).
 67:  *
 68:  * Its presence means this candidate's row rests on fewer episodes than
 69:  * the rest of the table, which qualifies every number in that row.
 70:  */
 71: export interface StoppedEarly {
 72:   episodes_run: number;
 73:   episodes_planned: number;
 74:   gate: string;
 75:   rule: string;
 76:   evidence?: Record<string, unknown>;
 77: }
 78: 
 79: /** How one episode ended, for one candidate.
 80:  *
 81:  * The four failure reasons are HÄ-6's buckets and they are not
 82:  * interchangeable: thirty collisions and thirty timeouts give the same
 83:  * `success_rate` and ask for completely different work. `success_rate`
 84:  * alone was the whole story until now, and it says how much went wrong
 85:  * without saying which part or how.
 86:  */
 87: export interface EpisodeOutcome {
 88:   episode_context_id: string;
 89:   success: boolean;
 90:   /** Null on success â€” never "no reason recorded". */
 91:   failure_reason: "no_path" | "collision" | "timeout" | "stuck" | null;
 92:   collision_count: number;
 93:   min_clearance: number;
 94:   travel_time_s: number;
 95:   p99_latency_ms: number;
 96:   /** How many times the stack replanned in this episode.
 97:    *
 98:    * Evidence, never a score: the cost of replanning is time and latency,
 99:    * and both are already charged. Absent on runs recorded before
100:    * replanning was priced â€” and 0 would be the true answer for them, but
101:    * `undefined` says "not recorded" instead of asserting it. */
102:   replan_count?: number;
103: }
104: 
105: export interface RunCandidate {
106:   candidate_id: string;
107:   stack_label: string;
108:   local_controller_config: string;
109:   /** What this candidate was allowed to see.
110:    *
111:    * Null means the registry has never heard of the stack, so nobody
112:    * declared its inputs â€” rendered as "not declared" rather than as a
113:    * plausible class, because inventing one would fabricate the single
114:    * fact a reader checking fairness came for.
115:    */
116:   global_observation_class?: string | null;
117:   local_observation_class?: string | null;
118:   gates: Record<string, GateVerdict>;
119:   cleared_gates: boolean;
120:   blocking_gates: string[];
121:   n_episodes?: number;
122:   n_distinct_episodes: number;
123:   /** Non-null when this candidate was retired before the sweep ended. */
124:   stopped_early?: StoppedEarly | null;
125:   success_rate: number;
126:   pooled_p99_latency_ms: number;
127:   /** Replans across every episode this candidate ran. See
128:    *  `EpisodeOutcome.replan_count` â€” evidence, not a score. */
129:   replan_count?: number;
130:   /** Per-episode outcomes, in the order the sweep ran them.
131:    *
132:    * **Absent is "not recorded", never "all passed".** Runs stored before
133:    * this field existed carry no episode rows, and rendering their
134:    * absence as a clean table would turn a report that measured nothing
135:    * per-episode into one that measured everything. The list endpoint
136:    * also strips this â€” ten warehouse runs of 600 rows each is close to a
137:    * megabyte on a page that draws none of them â€” so a component holding
138:    * a run from `listDecisions` must expect it missing.
139:    */
140:   episodes?: EpisodeOutcome[];
141: }
142: 
143: export interface RunSample {
144:   n_episodes: number;
145:   /** What was asked for, beside what was measured. Without it an
146:    *  interrupted run reads as a deliberate short one. */
147:   n_episodes_requested?: number;
148:   interrupted?: boolean;
149:   n_min_required: number;
150:   episode_context_ids: string[];
151: }
