212: export interface DecisionRun {
213:   id: string;
214:   task_profile_id: string;
215:   artifact_kind: ArtifactKind;
216:   experiment_scope: string | null;
217:   contracts_version: string;
218:   created_at: string;
219:   created_by: string | null;
220:   /** `false` means the field could not be ranked. Not an error â€” the
221:    *  gate table still says who was eliminated where. */
222:   ranked: boolean;
223:   recommended_candidate_id: string | null;
