566: /** The six gates, in contract order. Rendered in this order always, so
567:  *  a reader comparing two runs is comparing the same rows. */
568: export const GATES = ["G1", "G2", "G3", "G4", "G5", "G6"] as const;
569: 
570: /** Why this run produced no card â€” reduced to the one thing a reader
571:  *  has to do about it.
572:  *
573:  * Three outcomes, three different next actions, and collapsing them into
574:  * "no card" is what makes a gate table read like a failure:
575:  *
576:  * - `interrupted` â€” the run stopped early; what it did measure is valid
577:  *   and smaller. Run the rest.
578:  * - `gate_only` â€” this *deployment* cannot rank at all. No candidate
579:  *   would ever change that; use one whose threshold leaves room above it.
580:  * - `no_survivors` â€” fewer than two candidates cleared the gates.
581:  *   Register a better candidate. Never a softer deployment.
582:  */
583: export type NoCardReason = "interrupted" | "gate_only" | "no_survivors" | null;
584: 
585: export function noCardReason(run: DecisionRun): NoCardReason {
586:   if (run.ranked) return null;
587:   if (run.report?.sample?.interrupted) return "interrupted";
588:   if (run.report?.gate_only_deployment) return "gate_only";
589:   return "no_survivors";
590: }
