592: /** One candidate's episode outcomes, keyed by episode.
593:  *
594:  * A map rather than the array because the two candidates in a run do not
595:  * share an index: early stopping retires one of them mid-sweep, so row
596:  * seven of one array and row seven of the other can be different
597:  * episodes. Only the episode id lines them up.
598:  */
599: export function outcomesByEpisode(candidate: RunCandidate): Map<string, EpisodeOutcome> {
600:   return new Map((candidate.episodes ?? []).map((episode) => [episode.episode_context_id, episode]));
601: }
