603: /** Did any candidate in this run report per-episode outcomes?
604:  *
605:  * Used to tell "this run passed every episode" from "this run predates
606:  * the field", which look identical if you only count failures.
607:  */
608: export function hasEpisodeOutcomes(run: DecisionRun): boolean {
609:   return (run.report?.candidates ?? []).some((candidate) => candidate.episodes !== undefined);
610: }
611: 
612: /** What a run concluded, as something a person reads at a glance.
613:  *
614:  * The list used to print `recommended_candidate_id` â€” a hex hash. It is
615:  * the right identity for a trace path and the wrong thing to show
616:  * somebody scanning ten rows for the run that chose something.
617:  *
618:  * `cleared`/`total` travels with the winner because a recommendation out
619:  * of two survivors and one out of five are different claims, and the
620:  * gates are what separate them (HÄ-7): a candidate that failed a gate
621:  * was never ranked at all.
622:  */
623: export interface RunOutcome {
624:   winner: string | null;
625:   cleared: number;
626:   total: number;
627: }
628: 
629: export function runOutcome(run: DecisionRun): RunOutcome {
630:   const candidates = run.report?.candidates ?? [];
631:   const recommended = candidates.find(
632:     (candidate) => candidate.candidate_id === run.recommended_candidate_id,
633:   );
634:   return {
635:     winner: recommended
636:       ? `${recommended.stack_label} Â· ${recommended.local_controller_config}`
637:       : // The hash, only when the report cannot name the winner â€” better
638:         // than an em dash on a run that did recommend somebody.
639:         run.recommended_candidate_id,
640:     cleared: candidates.filter((candidate) => candidate.cleared_gates).length,
641:     total: candidates.length,
642:   };
643: }
