645: /** How many of the requested episodes a run actually covers.
646:  *
647:  * `undefined` when the report predates the field, which is different
648:  * from "covered everything" and must not render as 100%.
649:  */
650: export function coverage(run: DecisionRun): number | undefined {
651:   const requested = run.report?.sample?.n_episodes_requested;
652:   const measured = run.report?.sample?.n_episodes;
653:   if (!requested || measured === undefined) return undefined;
654:   return measured / requested;
655: }
