792: /** What deleting a deployment would destroy, as the server counted it. */
793: export interface DeletionBlocked {
794:   runs: number;
795:   ranked?: number;
796:   reviewed?: number;
797:   approved: number;
798:   /** Present only on the refusal no confirmation can answer.
799:    *
800:    * A deployment with plain runs asks a question ("delete 7 runs?"). One
801:    * with an approved run does not: the approval and its review trail are
802:    * what HÄ-14 exists to keep, so the way through is to withdraw the
803:    * approval, not to press harder. The ids are here so the dialog can
804:    * link to the runs instead of leaving somebody to find them. */
805:   approved_ids?: string[];
806: }
807: 
808: /** Delete a deployment.
809:  *
810:  * **Two outcomes, and the difference is whether anything was measured.**
811:  * A deployment nobody ran deletes straight away. One with stored runs is
812:  * refused with a 409 whose body carries the counts â€” because every run
813:  * is a statement *about* this deployment, and removing it turns
814:  * measurements into records of nothing.
815:  *
816:  * Resolves to `null` when it deleted, or to the counts when it was
817:  * refused. The counts are the server's, not a second tally made here:
818:  * a number the browser worked out for itself would be free to disagree
819:  * with the one the refusal was based on.
820:  */
821: export async function deleteTaskProfile(
822:   profileId: string,
823:   options: { deleteRuns?: boolean } = {},
824: ): Promise<DeletionBlocked | null> {
825:   const query = options.deleteRuns ? "?delete_runs=true" : "";
826:   try {
827:     await authFetch<{ id: string; deleted_runs: number }>(
828:       `/task-profiles/${encodeURIComponent(profileId)}${query}`,
829:       { method: "DELETE" },
830:     );
831:     return null;
832:   } catch (caught) {
833:     const blocked = blockedBy(caught);
834:     if (blocked) return blocked;
835:     throw caught;
836:   }
837: }
838: 
839: /** The counts inside a 409, or null if this was some other failure.
840:  *
841:  * Narrow on purpose: an error that is not the "it has runs" refusal must
842:  * keep travelling, or a network fault would open a confirmation dialog
843:  * offering to delete measurements that are still there.
844:  */
845: function blockedBy(error: unknown): DeletionBlocked | null {
846:   const first = error instanceof FieldError ? error.raw[0] : undefined;
847:   if (first && typeof first === "object" && typeof (first as DeletionBlocked).runs === "number") {
848:     return first as DeletionBlocked;
849:   }
850:   return null;
851: }
