 979: function GateCell({ verdict }: { verdict: GateVerdict | undefined }) {
 980:   const result = gateResult(verdict);
 981:   if (result === undefined) return <span className="muted">â€”</span>;
 982:   // The same badge whichever shape the verdict arrived in. A gate that
 983:   // serialised as the bare string "pass" is not a lesser judgement than
 984:   // one that carried evidence, and rendering it as plain text beside
