173:  // read the card rather than list order.
174:  const candidates = useMemo(
175:    () => panelCandidates(run, run.report?.candidates ?? []),
176:    [run],
177:  );
178:  const episodes = run.report?.sample?.episode_context_ids ?? [];
179:  const [episodeId, setEpisodeId] = useState(episodes[0] ?? "");
180:  const [slots, setSlots] = useState<Record<string, TraceSlot>>({});
181:  const [mode, setMode] = useState<"flat" | "raised">("flat");
182:  // Named `syncMode`, not `mode`: `mode` above is how the map is *drawn*
183:  // (2D or 2.5D). Two unrelated ideas under one name is how a later
184:  // reader concludes the page already had two sync modes.
185:  const [syncMode, setSyncMode] = useState<"time" | "progress">("time");
186:  const [sync, setSync] = useState<SyncSlot>({ state: "idle" });
187:  /** Empty until the recipe answers, and empty for a run too old to
188:   *  carry per-episode utility â€” the plain list is the honest fallback,
189:   *  not a set chosen another way under a preregistered label. */
190:  const [exemplars, setExemplars] = useState<Exemplar[]>([]);
191:  const [playback, setPlayback] = useState<PlaybackState>(initialPlayback);
192:  /** Where the progress playhead is, in metres of arc length. A second
193:   *  state rather than reusing `playback.time`, whose unit is seconds â€”
194:   *  one variable holding two units is a bug waiting for a reader. */
195:  const [scan, setScan] = useState<PlaybackState>(initialPlayback);
196:  const comparisonRef = useRef<HTMLDivElement | null>(null);
197:  const requestId = useRef(0);
198:
199:  const loadPair = useCallback(async (episode: string) => {
200:    const currentRequest = ++requestId.current;
201:    setPlayback(initialPlayback);
202:    setSlots(Object.fromEntries(candidates.map((candidate) => [candidate.candidate_id, { state: "loading" }])));
203:    await Promise.all(candidates.map(async (candidate) => {
204:      const outcome = outcomesByEpisode(candidate).get(episode);
205:      if (!outcome) {
206:        if (currentRequest === requestId.current) {
207:          setSlots((current) => ({ ...current, [candidate.candidate_id]: { state: "missing" } }));
208:        }
209:        return;
210:      }
211:      try {
212:        const trace = await getTrace(run.id, candidate.candidate_id, episode);
213:        if (currentRequest === requestId.current) {
214:          setSlots((current) => ({ ...current, [candidate.candidate_id]: trace.x.length > 0 ? { state: "ready", trace } : { state: "empty" } }));
215:        }
216:      } catch (caught) {
217:        if (currentRequest !== requestId.current) return;
218:        const message = caught instanceof Error ? caught.message : String(caught);
219:        setSlots((current) => ({
220:          ...current,
221:          [candidate.candidate_id]: /404|not found|does not exist/i.test(message)
222:            ? { state: "missing" }
223:            : { state: "error", message },
224:        }));
225:      }
226:    }));
227:  }, [candidates, run.id]);
228:
229:  useEffect(() => {
230:    if (episodeId) void loadPair(episodeId);
231:  }, [episodeId, loadPair]);
232:
233:  useEffect(() => {
234:    let live = true;
235:    getExemplars(run.id)
236:      .then((set) => {
237:        if (!live) return;
238:        // Fail closed on disagreement. The server reads the card and so
239:        // does this page, so they should never differ â€” and if they ever
240:        // do, four chips labelling episodes of *another* pair is worse
241:        // than no chips.
242:        const shown = candidates.map((candidate) => candidate.candidate_id);
243:        const about = [set.candidate_a, set.candidate_b];
244:        setExemplars(about.every((id) => shown.includes(id)) ? set.exemplars : []);
245:      })
246:      .catch(() => live && setExemplars([]));
247:    return () => {
248:      live = false;
249:    };
250:  }, [candidates, run.id]);
251:
252:  // Progress-sync is computed by the platform, not here: projecting in
253:  // the browser would put a second copy of the arc-length rules in
254:  // TypeScript, and the two would drift the first time either is fixed.
255:  useEffect(() => {
256:    if (syncMode !== "progress" || !episodeId || candidates.length < 2) return;
257:    let live = true;
258:    setSync({ state: "loading" });
259:    setScan(initialPlayback);
260:    getReplaySync(run.id, episodeId, candidates[0].candidate_id, candidates[1].candidate_id)
261:      .then((view) => live && setSync({ state: "ready", view }))
262:      .catch((caught: unknown) =>
263:        live &&
264:        setSync({ state: "error", message: caught instanceof Error ? caught.message : String(caught) }),
265:      );
266:    return () => {
267:      live = false;
268:    };
269:  }, [candidates, episodeId, run.id, syncMode]);
